from gklib import L, S, Q
L("earth","day-night-and-seasons","8-10","Day, Night and the Seasons","Two different tilts and spins explain why we have day and night and why summer and winter happen.","🌗",[
 S("Earth spins","Earth spins around like a top once every 24 hours. | The side facing the Sun has day, and the side facing away has night. | The spin makes the Sun seem to rise in the east and set in the west.",["One spin = 24 hours","Facing the Sun: day","Facing away: night"],"day-night"),
 S("Earth travels","While spinning, Earth also travels around the Sun. | One trip takes about 365 and a quarter days, which we call a year. | That extra quarter day is why we add a leap day every four years.",["One trip = one year","365 and a quarter days"],"seasons"),
 S("The tilt makes seasons","Earth's axis, the line it spins around, is tilted by about 23 and a half degrees. | When the northern half leans toward the Sun, it gets more direct light and longer days, so it is summer there. | At the same time the southern half leans away and has winter.",["Axis tilted about 23.5 degrees","Leaning toward the Sun: summer","Leaning away: winter"],"seasons"),
 S("A common mistake","Seasons are not caused by Earth being closer to or farther from the Sun. | In fact Earth is a little closer to the Sun in early January, when it is winter in the north. | It is the tilt that matters.",["Distance is not the cause","The tilt is the cause"]),
],facts=["Near the equator the days and nights stay about 12 hours long all year.","At the poles the Sun can stay up for months, and then stay below the horizon for months.","Earth spins at about 1,600 kilometres per hour at the equator."],
quiz=[Q("What causes day and night?",["Earth's spin","Earth's tilt","The Moon"],0,"Earth's spin turns each place toward and away from the Sun every 24 hours."),
Q("What causes the seasons?",["Distance from the Sun","The tilt of Earth's axis","Clouds"],1,"The tilt changes how directly sunlight hits each half of Earth during the year."),
Q("How long does Earth take to go once around the Sun?",["24 hours","About 365 days","30 days"],1,"One trip around the Sun is a year.")],tags=["seasons","rotation","tilt"])

L("earth","the-water-cycle","5-7","The Water Cycle","Follow a drop of water as it rises, becomes a cloud, falls as rain and runs back to the sea.","💧",[
 S("The Sun heats water","The Sun warms the water in oceans, rivers and puddles. | Some of the water turns into an invisible gas called water vapour and rises into the air. | This is called evaporation.",["Sun warms water","Water becomes vapour","Evaporation"],"water-cycle"),
 S("Clouds form","High up, the air is cold. | The water vapour cools down and turns back into tiny drops of water. | Millions of drops together make a cloud. This is called condensation.",["Cold air cools vapour","Tiny drops make clouds","Condensation"],"water-cycle"),
 S("Rain falls","When the drops in a cloud get big and heavy, they fall as rain. | In very cold places they fall as snow or hail. | This is called precipitation.",["Heavy drops fall","Rain, snow or hail","Precipitation"],"water-cycle"),
 S("Back to the sea","Rain runs down hills into streams and rivers, and flows back to the sea. | Some soaks into the ground and becomes groundwater. | Then the Sun warms it again, and the cycle goes on and on.",["Rivers carry water to the sea","Some soaks into the ground","The cycle repeats"]),
],facts=["The water you drink today may be the same water that dinosaurs drank, it just keeps going round.","About 97 percent of Earth's water is salty ocean water.","A fluffy cloud can weigh as much as about a hundred elephants, held up by the rising air."],
quiz=[Q("What is it called when water turns into vapour?",["Condensation","Evaporation","Precipitation"],1,"Evaporation is water changing to vapour."),
Q("What makes a cloud?",["Smoke","Tiny drops of water","Cotton"],1,"A cloud is millions of tiny water drops or ice crystals."),
Q("Which word means rain, snow or hail falling?",["Precipitation","Evaporation","Reflection"],0,"Precipitation is water falling from clouds.")],tags=["water","rain","cycle"])

L("earth","inside-the-earth-volcanoes-and-quakes","11-13","Inside the Earth: Volcanoes and Earthquakes","Look at the layers of the Earth and see why the ground shakes and volcanoes erupt.","🌋",[
 S("Layers of the Earth","Earth has four main layers: the crust, the mantle, the outer core and the inner core. | The crust is the thin rocky skin we live on. | Under it the mantle is hot, thick rock that moves very slowly, and at the centre the core is mostly iron and nickel.",["Crust: thin outer skin","Mantle: hot thick rock","Core: iron and nickel"],"volcano"),
 S("Moving plates","The crust is broken into huge pieces called tectonic plates. | They float on the mantle and move a few centimetres every year, about as fast as your fingernails grow. | Where plates meet, they can push together, pull apart or slide past each other.",["Plates move slowly","Where they meet things happen"],"plate-tectonics"),
 S("Earthquakes","Plates sometimes stick against each other as they try to move. | When the stress becomes too much, the rock suddenly slips and sends out shaking waves. | That sudden slip is an earthquake, and scientists measure its strength with a seismograph.",["Plates stick, then slip","Waves shake the ground"],"plate-tectonics"),
 S("Volcanoes","A volcano is an opening where melted rock called magma rises up from below. | Once it reaches the surface it is called lava. | Many volcanoes lie along the edges of plates, including the famous Ring of Fire around the Pacific Ocean.",["Magma below, lava above","Often at plate edges"],"volcano"),
],facts=["The Himalayas are still growing taller by a few millimetres a year because India's plate keeps pushing into Asia.","The deepest hole humans have drilled is about 12 kilometres, which is less than one half of one percent of the way to the centre.","Some volcanoes erupt under the sea."],
quiz=[Q("What are the main layers of the Earth in order from the top?",["Core, mantle, crust","Crust, mantle, core","Mantle, crust, core"],1,"From the outside in: crust, mantle, outer core, inner core."),
Q("What is melted rock called after it reaches the surface?",["Magma","Lava","Ash"],1,"Underground it is magma, and on the surface it is lava."),
Q("What is the cause of most earthquakes?",["Strong winds","Sudden slipping of rock along a fault","Heavy rain"],1,"Rocks slip suddenly when stress builds along plate edges.")],tags=["volcano","earthquake","plates"])

L("earth","how-weather-works","8-10","How Weather Works","Why the wind blows, how clouds make rain and what a monsoon is.","⛅",[
 S("Weather vs climate","Weather is what the air is like today: sunny, rainy, windy or hot. | Climate is the usual weather of a place over many years. | So a rainy day in Chennai is weather, but hot summers are part of its climate.",["Weather: today","Climate: the usual pattern"]),
 S("Warm air rises","The Sun warms the ground, and the ground warms the air above it. | Warm air is lighter, so it rises, and cooler air rushes in to take its place. | That moving air is the wind.",["Warm air rises","Cool air moves in","This is wind"]),
 S("Clouds and rain","As warm, moist air rises it cools, and the water vapour turns into tiny drops that make clouds. | When the drops grow heavy enough, they fall as rain. | Tall dark clouds can also build up electric charge, which gives us lightning and thunder.",["Rising air cools","Drops form clouds","Heavy drops fall"]),
 S("The monsoon","In summer the land of India heats up faster than the sea. | Warm air over land rises and pulls in wet winds from the ocean, and this gives us the southwest monsoon rains. | In winter the wind direction reverses, and Tamil Nadu gets much of its rain from the northeast monsoon.",["Land heats faster than sea","Winds bring ocean moisture","Monsoon winds reverse in winter"]),
],facts=["Lightning is about five times hotter than the surface of the Sun.","You can estimate how far a storm is by counting the seconds between lightning and thunder, and dividing by three to get kilometres.","The word monsoon comes from an Arabic word meaning season."],
quiz=[Q("Which one is climate?",["It rained today","Chennai is usually hot and humid","The wind is strong now"],1,"Climate is the usual weather over many years."),
Q("What is wind?",["Moving air","Moving clouds","Moving water"],0,"Wind is air moving from cooler, higher-pressure places toward warmer, lower-pressure places."),
Q("Tamil Nadu gets much of its rain from which monsoon?",["Southwest","Northeast","Neither"],1,"Most of Tamil Nadu's rain arrives with the northeast monsoon from October to December.")],tags=["weather","monsoon","wind"],notes="Rain timing differs from year to year; the monsoon months given are the usual pattern.")
